css:
:root {
    --global-h4-font-size: 32px;
    --global-h5-font-size: 24px;
    --global-h6-font-size: 20px;
}

/*Start - Change all titles to caps by WB Nicolas V*/
/*START - Makes Global Font titlecase*/
h1,
h2,
h3,
h4,
h5,
.lp-h1,
.lp-h2,
.lp-h3,
.lp-h4,
.lp-h5 {
    text-transform: uppercase ;
}
/*END*/


/*font-variation-settings specific to the visionary. */
/*if you experiment something funky with a different font, try to remove below CSS*/
.lp-h1,
.lp-h2,
.lp-h3{
    font-variation-settings: 'opsz' 44, 'GRAD' 0, 'slnt' 0, 'XTRA' 510, 'XOPQ' 96, 'YOPQ' 40, 'YTLC' 540, 'YTUC' 712, 'YTAS' 750, 'YTDE' -220, 'YTFI' 738;
}

.watermark {
    font-variation-settings: 'GRAD' 0, 'slnt' 0, 'XTRA' 511, 'XOPQ' 96, 'YOPQ' 50, 'YTLC' 537, 'YTUC' 712, 'YTAS' 750, 'YTDE' -221, 'YTFI' 738, 'opsz' 44;
}

/*end of font-variation-settings*/

/*START - home val search bar*/
.pac-item:hover {
    background-color: #042D49;
    span{
        color: #fff !important;
    }
}
/*END - home val search bar*/

/* START - Fix custom intro arrow button theme */
.custom-intro__scroll-btn,
.agent-intro__scroll-btn,
.neighborhood-intro__scroll-btn,
.blog-post-intro__scroll-btn{
    border-color: #fff;
    background: transparent;
}

.custom-intro__scroll-btn:after,
.agent-intro__scroll-btn:after,
.neighborhood-intro__scroll-btn:after,
.blog-post-intro__scroll-btn:after {
    background: #fff;
}

.custom-intro__scroll-btn:hover,
.agent-intro__scroll-btn:hover,
.neighborhood-intro__scroll-btn:hover,
.blog-post-intro__scroll-btn:hover {
    border-color: #fff;
    background: #fff;
}

.custom-intro__scroll-btn:hover:after,
.agent-intro__scroll-btn:hover:after,
.neighborhood-intro__scroll-btn:hover:after,
.blog-post-intro__scroll-btn:hover:after {
    background: #000;
}
/* END */

/*START - Custom Intro Box global theming*/
.custom-intro__content-box,
.agent-intro__content-box,
.neighborhood-intro__content-box,
.blog-post-intro__content-box {
    background-color:rgba(0, 0, 0, 0.9);
}

.custom-intro__pre-title,
.agent-intro__pre-title,
.neighborhood-intro__pre-title,
.blog-post-intro__pre-title,
.custom-intro__title,
.agent-intro__title,
.neighborhood-intro__title,
.blog-post-intro__title,
.custom-intro__title--with-pretitle:before,
.agent-intro__title--with-pretitle:before,
.neighborhood-intro__title--with-pretitle:before,
.blog-post-intro__title--with-pretitle:before{
    color: #fff;
}
/*END - Custom Intro Box global theming*/

/*Start - Custom Intro Center Button*/
.custom-intro{
    &__scroll-btn {
        border: 1px solid #fff;
        background-color: #fff;
        &:after{
            background: #000;
        }
        &:hover {
            border: 1px solid #fff;
            background-color: transparent;
            &:after{
                background: #fff;
            }
        }
    }

    &__title--with-pretitle {
            &:before{
                    border-color: #EAE710;
            }
    }
}
/*End - Custom Intro Button*/

/* START - Fix pagination slider arrows on hover globally */
.lp-arrow {
    border-color: #000;
    background: TRANSPARENT;

    &:after {
        background: #000;
    }
}

.lp-arrow:hover:not(:disabled) {
    border-color: #000;
    background:  #000;

    &:after {
        background: #FFF;
    }
}

/* END */

/*Fix arrow and dropdown in modal element - WB */
.modal .modal-content{
    .custom-select{
        .custom-select-toggle.is-placeholder {
            color: #000000;
        }
        .custom-select-toggle:after{
            background-color: #56769F;
        }
        .custom-select-item:hover{
            background-color: #56769F;
            color: #fff;
        }
    }
}
/*END*/

@media only screen and (max-width: 767px){
    .lp-close {
        right: 2vw;
        top: 2vh;
    }
}
.close .lp-close-icon, .close img {
    filter: invert(0) !important;
}

.custom-form {
    color: #fff;
    background-color: #495057!important;
    &__header{
        max-width: 860px;
    }
    &__download-form {
        justify-content: center;
    }
    @media only screen and (max-width: 768px){
        &__heading{
            font-size: 27px;
        }
    }
}

.lp-input {
    background: #fff;
    color: #000;
    &:hover{
        border-color: transparent;
        background: #fff;
        color: #000;
    }
    &:focus{
        border-color: transparent;
        background: #000;
        color: #fff;
    }
    &:not(:placeholder-shown):invalid{
        border-color: transparent;
        background: #000;
        color: #fff;
    }
}

.custom-select{
    .custom-select-content {
        background-color: #fff!important;
        color: #000 !important;
    }
    .custom-select-item:hover {
        background-color: #000!important;
        color: #fff !important;
    }
    .custom-select-item.is-selected {
        background-color: #000!important;
        color: #fff !important;
    }
}

.custom-form__heading {
    text-transform: uppercase;
    font-size: var(--global-h2-font-size);
}

.custom-form__footer {
    justify-content: center;
}

@media only screen and (max-width: 767px){
    .modals>.modal .close, body>.modal .close {
        right: 2vw !important;
        top: 2vh !important;
    }
}

