/*Start - Global Header Navbar - WB */
#global-navbar{
    .header-container{
        .header-navigation__link{
            text-transform: uppercase;
            letter-spacing: 1px;
            &:after{
                background-color: #000000;
            }
            &:before{
                background-color: #003DA5;
            }
        }
        .header-navigation__sub-nav {
            padding: 0;
            li{
                &:hover {
                    background-color: #000;
                    a{
                        color: #fff;
                    }
                }
            }
            .header-navigation__sub-nav-link{
                color: #000;
                text-transform: uppercase;
                letter-spacing: 1px;
                padding: 1rem
            }
        }
        .header-search-btn{
            border-color: #DA1A2C;
            &:after {
                    background-color: #DA1A2C;
                }
            &:hover {
                background-color: #DA1A2C;
                &:after {
                    background-color: #FFF;
                }
            }
        }
        .header-hamburger-btn:empty{
            border-color: #DA1A2C;
            &:before, &:after{
                    background-color: #DA1A2C;
                }
            &:hover {
                background-color: #DA1A2C;
                &:before, &:after{
                    background-color: #fff;
                }
            }
        }
    }
    .header.scroll{
        background-color: rgba(248, 248, 248, .9) !important;
        color: #000 !important;

    }
    @media (max-width: 768px) {
        .header {
            background-color: #f8f8f8!important;
        }
    }
}
/*End - Global Header Navbar - Nicolas V*/

