/*Sidemenu close button on hover - WB  */
div#global-sidemenu .sidemenu-close{
    color: #F4C35D;
    border-color: #F4C35D;
    &:hover:after{
        background: #102E4F!important;
    }
}

div#global-sidemenu .sidemenu-close:hover {
    background-color: #F4C35D;
}
/*End */

/*Fix cut off items on side menu - WB  */
div#global-sidemenu .sidemenu-navigation__link,
div#global-sidemenu .sidemenu-navigation-sub-nav__link {
    text-transform: uppercase;
    letter-spacing: 1px;
    -webkit-line-clamp: unset;
    -webkit-box-orient: unset;
}
/*End */

/*Start - Menu links and lines on side menu - WB */
div#global-sidemenu .lp-a a:hover {
    text-decoration-color: #fff;
}

div#global-sidemenu .lp-a a:active {
    color: #fff!important;
}

div#global-sidemenu .lp-a a:focus {
    text-decoration-color: #fff!important;
}

div#global-sidemenu .sidemenu-navigation__link:hover {
    color: #fff;
    opacity: 1;
}

div#global-sidemenu .sidemenu-footer:before{
    background-color: #fff;
    opacity: .5;
}

/*END*/

/*Make gap consistent between titles - WB Nicoals V*/
@media (max-width: 768px) {
    div#global-sidemenu .sidemenu-nav-holder {
        gap: 28px;
    }
}
/*END*/

/*----------- SIDE MENU -----------*/

/*Start - Side menu - Avoid text cut-off on tablet view*/
div#global-sidemenu .sidemenu-navigation__link {
    -webkit-line-clamp: unset !important;
}

/*End*/


/* START - Fix side menu accomodating too much space */
/* Note: This also fixes the side menu links being wrapped with ellipsis*/
/* Example: Home Val... to Home Valuation */
.sidemenu:has(.sidemenu-wrapper) {
    @media (min-width: 769px) {
        width: auto;
    }
}

/* END */

/* START - Fix side menu scroll not calculating the overall height */
.sidemenu-wrapper {
    min-height: fit-content;
    max-height: 100%;
}

/* END */

/* START - Fix side menu width depending on the column number of links */
/* Note: The side menu can only contain a maximum of 4 column */
.sidemenu-nav-holder {
    @media (min-width: 1025px) {
        &:has(> .sidemenu-navigation:nth-child(1):last-child) {
            grid-template-columns: auto;
        }

        &:has(> .sidemenu-navigation:nth-child(2):last-child) {
            grid-template-columns: auto auto;
        }

        &:has(> .sidemenu-navigation:nth-child(3):last-child) {
            grid-template-columns: auto auto auto;
        }

        &:has(> .sidemenu-navigation:nth-child(4):last-child) {
            grid-template-columns: auto auto auto auto;
        }
    }

    @media (max-width: 768px) {
        gap: 28px !important;
    }
}

/* END */

/* START - Fix the side menu underline */
.sidemenu-wrapper {
    @media (max-width: 768px) {
        width: 100%;
    }
}

.sidemenu-footer {
    @media (min-width: 769px) {
        &:before {
            width: 100%;
        }
    }
}

.sidemenu-socials-block {
    width: 450px !important;

    @media (max-width: 768px) {
        &:before {
            width: 100%;
        }
    }
}

/* END */

/* START - Fix side menu large vertical paddings on mobile */
#global-sidemenu {
    @media (max-width: 768px) {
        padding-top: 128px;
        padding-bottom: 48px;
    }
}

/* END */

/* START - Fix the side menu contact details vertical padding */
.sidemenu-footer {
    @media (min-width: 1025px) {
        padding-top: 70px;
    }

    @media (max-width: 768px) {
        padding-top: 0px;
        padding-bottom: 0px;
    }
}

/* END */

/* START - Fix side menu office hours details not having 2nd line */
.sidemenu__col-description {
    white-space: pre-line;
}

/* END */

/* START - Reposition the side menu close button on mobile */
.sidemenu-close {
    @media (max-width: 768px) {
        top: 16px;
        right: 16px;
    }
}

/* END */

/*Start - Global Contact Form Modal - Nicolas V*/
#modal-global-contact-us{
    .contact-form-modal-details__title{
        max-width: 100%;
        color: #000;
    }
    .contact-form-modal-agent__contact {
        max-width: 100%;
        color: #000;
    }
    .contact-form-modal-agent__name, .lp-pre-line{
        text-transform: uppercase;
        letter-spacing: 1px;
    }
    .lp-label {
        font-size: 14px;
        font-weight: 500;
        text-transform: uppercase;
    }
    .lp-a a {
        text-transform: uppercase;
        letter-spacing: 1px;
        color: #000;
        &:hover{
            color: #818285;
            text-decoration-color: #818285;
        }
    }
    >.lp-close {
        @media (max-width: 1024px) {
        display: block;
        top: 3vh;
        }
    }
