    &:before {
        content: '';
        position: absolute;
        left: 0;
        bottom: 0;
        width: 100%;
        height: 1px;
        background: #ccc!important;
        -webkit-transition: .3s linear;
        -webkit-transition: .3s linear;
        transition: .3s linear;
    }
    &:after {
        content: '';
        position: absolute;
        left: 0;
        bottom: 0;
        width: 0%;
        height: 1px;
        background: #003DA5!important;
        -webkit-transition: .3s linear;
        -webkit-transition: .3s linear;
        transition: .3s linear;
    }
    &:hover{
        &:after{
            width: 100%;
        }
        color: #003DA5;
    }
}


